module panel_rom(input clk,input [13:0] map_address,input [3:0] row,
    output [31:0] text_row,input [8:0] digit_address,output [31:0] digit_row);
    wire [15:0] tile,text_bits;reg [3:0] row_q=0;
    always @(posedge clk)row_q<=row;
    panel_map_sp map(.clk(clk),.address(map_address),.data(tile));
    panel_text_sp text_pixels(.clk(clk),.address({tile[10:0],row_q}),.data(text_bits));
    genvar px;generate for(px=0;px<16;px=px+1)begin:expand_coverage
        assign text_row[px*2+:2]={2{text_bits[px]}};
    end endgenerate
    panel_digits_sp digit_pixels(.clk(clk),.address(digit_address),.data(digit_row));
endmodule
